CREATE TABLE IF NOT EXISTS recommendation_sessions (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE RESTRICT, preferences TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, completed_at TEXT);
CREATE TABLE IF NOT EXISTS recommendation_results (id INTEGER PRIMARY KEY, session_id INTEGER NOT NULL REFERENCES recommendation_sessions(id) ON DELETE CASCADE, restaurant_id INTEGER NOT NULL REFERENCES restaurants(id) ON DELETE RESTRICT, rank_position INTEGER NOT NULL, score REAL NOT NULL, confidence REAL NOT NULL, criteria TEXT NOT NULL, color_score REAL, color_hex TEXT, created_at TEXT NOT NULL, UNIQUE(session_id, restaurant_id));
CREATE TABLE IF NOT EXISTS recommendation_feedback (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE RESTRICT, result_id INTEGER NOT NULL REFERENCES recommendation_results(id) ON DELETE CASCADE, rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(user_id,result_id));
CREATE TABLE IF NOT EXISTS favorites (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE RESTRICT, restaurant_id INTEGER NOT NULL REFERENCES restaurants(id) ON DELETE RESTRICT, created_at TEXT NOT NULL, UNIQUE(user_id,restaurant_id));
CREATE TABLE IF NOT EXISTS tinder_sessions (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE RESTRICT, status TEXT NOT NULL, current_restaurant_id INTEGER REFERENCES restaurants(id), created_at TEXT NOT NULL, ended_at TEXT);
CREATE TABLE IF NOT EXISTS tinder_actions (id INTEGER PRIMARY KEY, session_id INTEGER NOT NULL REFERENCES tinder_sessions(id) ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE RESTRICT, restaurant_id INTEGER NOT NULL REFERENCES restaurants(id) ON DELETE RESTRICT, action TEXT NOT NULL CHECK(action IN ('like','dislike')), created_at TEXT NOT NULL, UNIQUE(session_id,restaurant_id));
CREATE INDEX IF NOT EXISTS idx_recommendation_user ON recommendation_sessions(user_id,created_at);
CREATE INDEX IF NOT EXISTS idx_results_session ON recommendation_results(session_id,rank_position);
CREATE INDEX IF NOT EXISTS idx_favorites_user ON favorites(user_id,id);
CREATE INDEX IF NOT EXISTS idx_tinder_actions_session ON tinder_actions(session_id,restaurant_id);
CREATE INDEX IF NOT EXISTS idx_logs_created ON logs(created_at);
